rows[18501]={title={{6,1433816283},"격노"},description={"^increases the physical damage dealt by the caster and speeds its attacks for ([%+%-]?%d[%d,.]* %a+)%.$","\0311\031 동안 시전자의 물리 공격력과 공격 속도가 증가합니다.",{1},{1}},aura={"^physical damage dealt is increased by ([%+%-]?%d[%d,.%+%-to –]*)%. attack speed increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","물리 공격력 \0311\031만큼 증가\010공격 속도 \0312\031%만큼 증가",{0,0},{1,2}}}
rows[18502]={title={{15,1480431505},"학카르의 저주"},description={"^drains ([%+%-]?%d[%d,.%+%-to –]*) mana from an enemy every ([%+%-]?%d[%d,.%+%-to –]*) sec%., transferring it to the caster over ([%+%-]?%d[%d,.]* %a+)%.$","\0313\031에 걸쳐 적으로부터 \0312\031초마다 \0311\031의 마나를 흡수하여 시전자에게 이전합니다.",{0,0,1},{1,2,3}},aura={"^([%+%-]?%d[%d,.%+%-to –]*) mana leeched every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","\0312\031초마다 \0311\031의 마나 흡수",{0,0},{1,2}}}
