rows[22274]={title={{17,1449157712},"상급 변이"},description={"^transforms an enemy into a sheep, forcing it to wander around for up to ([%+%-]?%d[%d,.]* %a+)%. while wandering, the sheep cannot attack or cast spells, but regenerates very quickly%. only one target can be polymorphed at a time%. only works on beasts, dragons, giants, humanoids, and critters%.$","최대 \0311\031 동안 적을 양으로 변이시켜 주변을 떠돌게 만듭니다. 떠도는 동안엔 공격하거나 주문을 외울 수 없지만 매우 빠른 속도로 체력이 회복됩니다. 한 번에 한 대상만 변이시킬 수 있으며 야수와 용, 거인, 인간형, 동물에게만 사용할 수 있습니다.",{1},{1}},aura={{60,2044060023},"마법 시전 및 공격 불가\010생명력 회복 속도 증가"}}
