rows[27556]={title={{4,257961109},"갈퀴 발톱"},description={"^rake the target for ([%+%-]?%d[%d,.%+%-to –]*) damage and an additional ([%+%-]?%d[%d,.%+%-to –]*) damage over ([%+%-]?%d[%d,.]* %a+)%.$","대상을 발톱으로 할퀴어 \0311\031의 피해를 입히고 추가로 \0313\031에 걸쳐 총 \0312\031의 피해를 입힙니다.",{0,0,1},{1,2,3}},aura={"^bleeding for ([%+%-]?%d[%d,.%+%-to –]*) damage every ([%+%-]?%d[%d,.%+%-to –]*) seconds%.$","\0312\031초마다 출혈로 \0311\031의 피해",{0,0},{1,2}}}
rows[27557]={title={{14,905967881},"흉포한 이빨"},description={"^deals ([%+%-]?%d[%d,.%+%-to –]*) damage to the target%.$","대상에게 \0311\031의 피해를 입힙니다.",{0},{1}}}
rows[27559]={title={{7,1257350788},"침묵"},description={"^silences an enemy preventing it from casting spells for ([%+%-]?%d[%d,.]* %a+)%.$","적을 침묵시켜 \0311\031 동안 마법 시전이 불가능하게 만듭니다.",{1},{1}},aura={{19,1268338028},"마법 시전 불가"}}
rows[27561]={title={{15,1631021486},"침묵 트리거"},description={"^when struck by a harmful spell, the caster of that spell has a ([%+%-]?%d[%d,.%+%-to –]*)%% chance to be silenced for ([%+%-]?%d[%d,.]* %a+)%.$","해로운 주문에 적중 당했을 때 \0311\031%의 확률로 해당 주문의 시전자는 \0312\031 동안 침묵에 걸리게 됩니다.",{0,1},{1,2}}}
rows[27564]={title={{10,2126960367},"반사"},description={"^gives the caster ([%+%-]?%d[%d,.%+%-to –]*)%% chance to reflect harmful spells for ([%+%-]?%d[%d,.]* %a+)%.$","\0312\031 동안 \0311\031%의 확률로 해로운 주문을 반사합니다.",{0,1},{1,2}},aura={"^([%+%-]?%d[%d,.%+%-to –]*)%% chance to reflect spells%.$","\0311\031%의 확률로 마법 반사",{0},{1}}}
rows[27565]={title={{6,2117079088},"추방"},description={"^banishes an enemy, preventing all action but making it invulnerable for up to ([%+%-]?%d[%d,.]* %a+)%. only one target can be banished at a time%.$","적을 차원의 저편으로 추방하여 어떤 행동도 하지 못하게 만듭니다. 최대 \0311\031 동안 이 대상에겐 어떤 피해도 입히지 못합니다. 동시에 한 대상만 추방할 수 있습니다.",{1},{1}},aura={{52,214105277},"모든 공격 및 주문에 면역\010모든 행동 불가"}}
rows[27567]={title={{15,1023701820},"연쇄 번개"}}
